solution:
#include <string>

std::string fizzbuzz(int n) {
    std::string result;
    for (int i = 1; i <= n; ++i) {
        if (i > 1) result += ' ';

        if (i % 15 == 0) {
            result += "FizzBuzz";
        } else if (i % 3 == 0) {
            result += "Fizz";
        } else if (i % 5 == 0) {
            result += "Buzz";
        } else {
            result += std::to_string(i);
        }
    }
    return result;
}
